(7015080, 1060440, 157824, '<td valign="top">looks like fantasy world. very nice</td>', 'looks like fantasy world. very nice', '2013-04-07 05:30:22.000000', NULL, 1),
(7015110, 1060180, 157824, '<td valign="top">The common macro problem - focus. This would be great if focused better with the more fstops around f10 which might require flash too. good attempt</td>', 'The common macro problem - focus. This would be great if focused better with the more fstops around f10 which might require flash too. good attempt', '2013-04-07 08:08:09.000000', NULL, 1),
(7015215, 1059840, 82999, '<td valign="top">In my opinion this could be an outstanding image.  As is its over processed.  Needs to be tack sharp.  And I put a figure in the chair in austere clothing head in hands. And a stronger vignette around the perimeter to draw the eye to the light and the figure.</td>', 'In my opinion this could be an outstanding image.  As is its over processed.  Needs to be tack sharp.  And I put a figure in the chair in austere clothing head in hands. And a stronger vignette around the perimeter to draw the eye to the light and the figure.', '2013-04-07 09:58:21.000000', NULL, 1),
(7015216, 1061621, 65234, '<td valign="top">Really wish I could vote on this!  You nailed the exposure perfectly.  Colors are gorgeous and there''s just the right amount of texture and movement in the water.</td>', 'Really wish I could vote on this!  You nailed the exposure perfectly.  Colors are gorgeous and there''s just the right amount of texture and movement in the water.', '2013-04-07 10:03:12.000000', NULL, 1),
(7015220, 1060567, 65234, '<td valign="top">Adore the light and that eye contact!  Beautiful bokeh and sharp detail everywhere it''s needed.</td>', 'Adore the light and that eye contact!  Beautiful bokeh and sharp detail everywhere it''s needed.', '2013-04-07 10:08:56.000000', NULL, 1),
(7015221, 1060581, 65234, '<td valign="top">Stunning light.  Looks like a fabulous place to see.</td>', 'Stunning light.  Looks like a fabulous place to see.', '2013-04-07 10:09:53.000000', NULL, 1),
(7015222, 1059924, 65234, '<td valign="top">Adorable sheeps :-). The soft light and pastels suit them.</td>', 'Adorable sheeps :-). The soft light and pastels suit them.', '2013-04-07 10:11:20.000000', NULL, 1),
(7015224, 1061015, 65234, '<td valign="top">I can believe there''s a pot of gold at the end of that rainbow.</td>', 'I can believe there''s a pot of gold at the end of that rainbow.', '2013-04-07 10:12:53.000000', NULL, 1),
(7015225, 1061902, 65234, '<td valign="top">Lovely tones.</td>', 'Lovely tones.', '2013-04-07 10:13:07.000000', NULL, 1),
