(7015247, 1061806, 122678, '<td valign="top">Well you really had me looking for the dove. Well titled make you really analyze the shot.</td>', 'Well you really had me looking for the dove. Well titled make you really analyze the shot.', '2013-04-07 11:19:04.000000', NULL, 1),
