(7015254, 1061826, 76335, '<td valign="top">Processing reminds me of an old process -- autochrome, maybe.</td>', 'Processing reminds me of an old process -- autochrome, maybe.', '2013-04-07 11:24:30.000000', NULL, 1),
(7015255, 1060772, 122678, '<td valign="top">Good use of lighting.</td>', 'Good use of lighting.', '2013-04-07 11:24:43.000000', NULL, 1),
