(7015258, 1061916, 122678, '<td valign="top">Awww...</td>', 'Awww...', '2013-04-07 11:26:09.000000', NULL, 1),
(7015259, 1059478, 76335, '<td valign="top">I like it. The foreground area has the feeling of being heavily blotted out by an eraser. The eraser of time? Of memory? Different. Totally captivating. A ten for you.</td>', 'I like it. The foreground area has the feeling of being heavily blotted out by an eraser. The eraser of time? Of memory? Different. Totally captivating. A ten for you.', '2013-04-07 11:26:22.000000', NULL, 1),
(7015260, 1060451, 122678, '<td valign="top">Well titled</td>', 'Well titled', '2013-04-07 11:27:07.000000', NULL, 1),
(7015268, 1061809, 76335, '<td valign="top">Nicely done. Such a peaceful and mature pose. Bottom edge feels a bit tight.</td>', 'Nicely done. Such a peaceful and mature pose. Bottom edge feels a bit tight.', '2013-04-07 11:33:19.000000', NULL, 1),
(7015269, 1061611, 76335, '<td valign="top">Reminds me of a book I just finished -- The Ruined Map. Nice story here. I like the blackness that allows for some mystery.</td>', 'Reminds me of a book I just finished -- The Ruined Map. Nice story here. I like the blackness that allows for some mystery.', '2013-04-07 11:34:34.000000', NULL, 1),
(7015271, 1061553, 76335, '<td valign="top">The colors feel a but muddy (the green in the hair, the shadows around her neck). But maybe that''s part of the appeal.</td>', 'The colors feel a but muddy (the green in the hair, the shadows around her neck). But maybe that''s part of the appeal.', '2013-04-07 11:36:09.000000', NULL, 1),
(7015272, 1061758, 76335, '<td valign="top">Quite a chilling expression...</td>', 'Quite a chilling expression...', '2013-04-07 11:36:29.000000', NULL, 1),
(7015273, 1060508, 71489, '<td valign="top">I like the colors here.</td>', 'I like the colors here.', '2013-04-07 11:37:43.000000', NULL, 1),
(7015274, 1061763, 71489, '<td valign="top">The shadows are distracting here.</td>', 'The shadows are distracting here.', '2013-04-07 11:37:58.000000', NULL, 1),
(7015275, 1061728, 76335, '<td valign="top">Three bird shots in a row. What are the odds of that? This is my favorite of the procession. I like how the branches fracture the frame.</td>', 'Three bird shots in a row. What are the odds of that? This is my favorite of the procession. I like how the branches fracture the frame.', '2013-04-07 11:38:22.000000', NULL, 1),
(7015276, 1061689, 76335, '<td valign="top">A new twist on still life. Nice.</td>', 'A new twist on still life. Nice.', '2013-04-07 11:39:06.000000', NULL, 1),
(7015277, 1060581, 71489, '<td valign="top">They actually look like sun rays. I like the tones. But the composition looks a little off actually.</td>', 'They actually look like sun rays. I like the tones. But the composition looks a little off actually.', '2013-04-07 11:39:36.000000', NULL, 1),
(7015278, 1061914, 76335, '<td valign="top">Nice twist on an old cliché.</td>', 'Nice twist on an old cliché.', '2013-04-07 11:39:57.000000', NULL, 1),
(7015280, 1061475, 71489, '<td valign="top">The lower left corner looks a little blown. And I think I see some noise here.</td>', 'The lower left corner looks a little blown. And I think I see some noise here.', '2013-04-07 11:40:39.000000', NULL, 1),
(7015281, 1061808, 71489, '<td valign="top">Surreal!</td>', 'Surreal!', '2013-04-07 11:41:07.000000', NULL, 1),
(7015282, 1061874, 76335, '<td valign="top">Effectively framed. The tiny smokestacks threaten to overtake the huge expanse of sky with their exhalations...</td>', 'Effectively framed. The tiny smokestacks threaten to overtake the huge expanse of sky with their exhalations...', '2013-04-07 11:41:47.000000', NULL, 1),
(7015284, 1061344, 71489, '<td valign="top">Lovely set up! Although maybe you couldn''t avoid it, the shadows are distracting.</td>', 'Lovely set up! Although maybe you couldn''t avoid it, the shadows are distracting.', '2013-04-07 11:44:29.000000', NULL, 1),
(7015286, 1060819, 71489, '<td valign="top">Its nice and sharp but it lacks symmetry. Maybe you could''ve moved a few steps further and kept the windows in the center of the picture.</td>', 'Its nice and sharp but it lacks symmetry. Maybe you could''ve moved a few steps further and kept the windows in the center of the picture.', '2013-04-07 11:45:35.000000', NULL, 1),
(7015288, 1061575, 16148, '<td valign="top">Your processing suits your subject and composition.  It all works well together.</td>', 'Your processing suits your subject and composition.  It all works well together.', '2013-04-07 11:47:24.000000', NULL, 1),
(7015290, 1059756, 71489, '<td valign="top">Ok. Should''ve been sharper. I see some noise on her face which could''ve been avoided. And the shadows shouldn''t have been there (left ear). Plus, if she was looking into the camera then it would''ve been awesome. Just my two cents.</td>', 'Ok. Should''ve been sharper. I see some noise on her face which could''ve been avoided. And the shadows shouldn''t have been there (left ear). Plus, if she was looking into the camera then it would''ve been awesome. Just my two cents.', '2013-04-07 11:47:52.000000', NULL, 1),
(7015291, 1057239, 71489, '<td valign="top">There''s nothing here that really stands out.</td>', 'There''s nothing here that really stands out.', '2013-04-07 11:48:14.000000', NULL, 1),
(7015293, 1061297, 71489, '<td valign="top">Lovely portrait. Especially the hair and snowflakes just complete the picture! If only I could see her right eye completely and you could''ve upped the saturation on her eyes it would''ve been awesome! 7!</td>', 'Lovely portrait. Especially the hair and snowflakes just complete the picture! If only I could see her right eye completely and you could''ve upped the saturation on her eyes it would''ve been awesome! 7!', '2013-04-07 11:49:28.000000', NULL, 1),
(7015294, 1061213, 71489, '<td valign="top">Joshua right? I really like how visible the smoke is. And the shadows behind her. However I don''t like the feeling that it looks like a photo of a photo. Was the noise intentional?</td>', 'Joshua right? I really like how visible the smoke is. And the shadows behind her. However I don''t like the feeling that it looks like a photo of a photo. Was the noise intentional?', '2013-04-07 11:51:24.000000', NULL, 1),
